import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents basic positive', () => {
  assert.equal(roundCents(123.4), 123);
  assert.equal(roundCents(123.5), 124);
  assert.equal(roundCents(123.6), 124);
});

test('roundCents banker rounding', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents negative', () => {
  assert.equal(roundCents(-0.5), 0);
  assert.equal(roundCents(-1.5), -2);
});

test('formatEuros positive', () => {
  assert.equal(formatEuros(12345), '€123.45');
  assert.equal(formatEuros(100), '€1.00');
  assert.equal(formatEuros(50), '€0.50');
});

test('formatEuros negative', () => {
  assert.equal(formatEuros(-12345), '-€123.45');
});

test('formatEuros thousands separator', () => {
  assert.equal(formatEuros(1234567), '€12,345.67');
});

test('parseEuros basic', () => {
  assert.equal(parseEuros('12').value, 1200);
  assert.equal(parseEuros('12.5').value, 1250);
  assert.equal(parseEuros('1,234.56').value, 123456);
});

test('parseEuros whitespace', () => {
  assert.equal(parseEuros('  12.5  ').value, 1250);
});

test('RATES constant exists', () => {
  assert.ok(RATES);
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert returns ok result', () => {
  const result = convert(10000, 'USD');

  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');

  assert.equal(result.ok, true);
  const euros = 100;
  const usd = euros * 1.085;
  const expectedCents = Math.round(usd * 100);
  assert.equal(result.value, expectedCents);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');

  assert.equal(result.ok, true);
  const euros = 100;
  const gbp = euros * 0.8425;
  const expectedCents = Math.round(gbp * 100);
  assert.equal(result.value, expectedCents);
});

test('convert EUR to EUR', () => {
  const result = convert(10000, 'EUR');

  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert unknown currency returns error', () => {
  const result = convert(10000, 'JPY');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert zero cents', () => {
  const result = convert(0, 'USD');

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert small amount', () => {
  const result = convert(1, 'USD');

  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('convert large amount', () => {
  const result = convert(10000000, 'USD');

  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('convert uses banker rounding', () => {
  const result = convert(115, 'GBP');

  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('formatMoney EUR uses € symbol', () => {
  const formatted = formatMoney(12345, 'EUR');

  assert.ok(formatted.includes('€'));
});

test('formatMoney USD uses $ symbol', () => {
  const formatted = formatMoney(12345, 'USD');

  assert.ok(formatted.includes('$'));
});

test('formatMoney GBP uses £ symbol', () => {
  const formatted = formatMoney(12345, 'GBP');

  assert.ok(formatted.includes('£'));
});

test('formatMoney positive amount', () => {
  const formatted = formatMoney(12345, 'USD');

  assert.match(formatted, /^\$\d+\.\d{2}$/);
});

test('formatMoney negative amount', () => {
  const formatted = formatMoney(-12345, 'USD');

  assert.ok(formatted.startsWith('-'));
});

test('formatMoney zero', () => {
  const formatted = formatMoney(0, 'USD');

  assert.equal(formatted, '$0.00');
});

test('formatMoney two decimal places', () => {
  const formatted = formatMoney(50, 'USD');

  assert.equal(formatted, '$0.50');
});

test('formatMoney thousands separator', () => {
  const formatted = formatMoney(1234567, 'USD');

  assert.ok(formatted.includes(','));
});

test('formatMoney format with comma thousands', () => {
  const formatted = formatMoney(1234567, 'USD');

  assert.equal(formatted, '$12,345.67');
});

test('formatMoney negative format', () => {
  const formatted = formatMoney(-123456, 'GBP');

  assert.equal(formatted, '-£1,234.56');
});

test('formatMoney sign before symbol', () => {
  const formatted = formatMoney(-100, 'EUR');

  assert.ok(formatted.startsWith('-'));
});

test('formatMoney unknown currency uses code', () => {
  const formatted = formatMoney(12345, 'XYZ');

  assert.ok(formatted.includes('XYZ'));
});

